(5504334, 793329, 91783, '<td valign="top">I absolutly LOVE this photo! this is my favorite out of all of the others. hope that you place in the top 3. good luck!</td>', 'I absolutly LOVE this photo! this is my favorite out of all of the others. hope that you place in the top 3. good luck!', '2009-05-29 02:07:10.000000', NULL, 1),
(5504335, 793378, 91783, '<td valign="top">it''s a good picture, but it would have been better if there was no bugs on the right front bumper. or front bumper in general. excellent photo besides that.</td>', 'it''s a good picture, but it would have been better if there was no bugs on the right front bumper. or front bumper in general. excellent photo besides that.', '2009-05-29 02:08:40.000000', NULL, 1),
