(5505518, 792513, 103069, '<td valign="top">Amazing photo.... very nice....(9)</td>', 'Amazing photo.... very nice....(9)', '2009-05-30 08:55:28.000000', NULL, 1),
(5505602, 793097, 73235, '<td valign="top">love the strong colors in the bottom half and the contrast to the contrasty sky. your angles are well aligned with the raod AND the horizon . You have no choice :) but to love this shot!!</td>', 'love the strong colors in the bottom half and the contrast to the contrasty sky. your angles are well aligned with the raod AND the horizon . You have no choice :) but to love this shot!!', '2009-05-30 11:32:16.000000', NULL, 1),
