(5507286, 792087, 28742, '<td valign="top">Congrats!</td>', 'Congrats!', '2009-06-01 01:03:03.000000', NULL, 0),
(5507292, 793426, 67237, '<td valign="top">A most technically perfect presentation. Worth to be in any Porsche catalog.<br/>Congrats on the HM brother!!!</td>', 'A most technically perfect presentation. Worth to be in any Porsche catalog.Congrats on the HM brother!!!', '2009-06-01 01:04:03.000000', NULL, 0),
(5507293, 793082, 28742, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Art Roflmao:</b></div><hr/><i> Wrap it up, I''ll take it. </i></td></tr></table> <br/>Correction: Wrap it up <b>and put a ribbon on it</b>. :) Congrats!</td>', 'Originally posted by Art Roflmao: Wrap it up, I''ll take it.  Correction: Wrap it up and put a ribbon on it. :) Congrats!', '2009-06-01 01:04:13.000000', NULL, 0),
(5507298, 793426, 28742, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Art Roflmao:</b></div><hr/><i> winner! You could have put some nice text on the photo, but why ruin it. :) Congrats - this will be on the front page. </i></td></tr></table> <br/>Dang - I hate being wrong. Maybe people preferred text on the image. :/ Congrats on a top 5!</td>', 'Originally posted by Art Roflmao: winner! You could have put some nice text on the photo, but why ruin it. :) Congrats - this will be on the front page.  Dang - I hate being wrong. Maybe people preferred text on the image. :/ Congrats on a top 5!', '2009-06-01 01:06:28.000000', NULL, 0),
