(5507316, 793376, 21255, '<td valign="top">i gave this an 8, without the txt it would have been a 10, alot of car ads are dark!</td>', 'i gave this an 8, without the txt it would have been a 10, alot of car ads are dark!', '2009-06-01 01:09:56.000000', NULL, 0),
